// The bundled example conversation, read back through the app's own parsers,
// and the placing that keeps it recent (src/helpers/sampleConversations.mjs).
// The fixtures are generated by demo/build-fixtures.mjs from demo/script/;
// these pin what the example has to show, so a change to a helper that would
// quietly break the example fails here.

const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const root = path.join(__dirname, "..", "..");
const example = require("../../src/helpers/sampleConversations/launch-readiness-review.json");
const demoDir = path.join(root, "demo", "fixtures");
const demoFixtures = fs
  .readdirSync(demoDir)
  .filter((name) => name.endsWith(".json"))
  .map((name) => JSON.parse(fs.readFileSync(path.join(demoDir, name), "utf8")));

let samples;
let review;
let talk;
let moments;
let loudness;
let flow;
let resume;
let lifetime;

test.before(async () => {
  samples = await import("../../src/helpers/sampleConversations.mjs");
  review = await import("../../src/helpers/conversationReview.mjs");
  talk = await import("../../src/helpers/talkTime.mjs");
  moments = await import("../../src/helpers/conversationMoments.mjs");
  loudness = await import("../../src/helpers/conversationLoudness.mjs");
  flow = await import("../../src/helpers/conversationFlow.mjs");
  resume = await import("../../src/helpers/conversationResume.mjs");
  lifetime = await import("../../src/helpers/lifetimeGraph.mjs");
});

const NOW = Date.UTC(2027, 2, 15, 18, 0, 0);

test("the example is a labelled sample in the app's own formats", () => {
  samples.assertSampleFixture(example);
  assert.equal(example.meta.sample, true);
  assert.equal(example.meta.id, "launch-readiness-review");
  assert.equal(example.note.note_type, "meeting");
  assert.match(example.note.enhanced_content, /^## Threads$/m);
  assert.ok(example.note.title.length > 0 && example.note.title.length < 100);
});

test("the example's transcript has nine named voices, the chair and the eng lead talking most", () => {
  const segments = example.note.transcript;
  assert.ok(segments.length > 200);
  const ids = new Set();
  for (const segment of segments) {
    assert.equal(typeof segment.id, "string");
    assert.ok(!ids.has(segment.id), `duplicate segment id ${segment.id}`);
    ids.add(segment.id);
    assert.ok(segment.endMs > segment.startMs);
    assert.match(segment.speaker, /^speaker_\d+$/);
    assert.equal(segment.speakerIsPlaceholder, false);
    assert.ok(segment.speakerName);
  }
  const voices = talk.talkTime(segments).speakers;
  assert.equal(voices.length, 9);
  assert.deepEqual(
    voices.slice(0, 2).map((voice) => voice.segment.speakerName),
    ["Maya", "Theo"]
  );
  assert.ok(voices.filter((voice) => voice.percent < 5).length >= 2);
  const minutes = (example.meta.endedAt - example.meta.startedAt) / 60000;
  assert.ok(minutes >= 28 && minutes <= 32, `${minutes} minutes`);
});

test("the example's questions come out every way a question can", () => {
  const { total, outcomes } = review.questionOutcomes(example.events);
  assert.ok(total >= 12 && total <= 16, `${total} questions`);
  const kinds = new Set(outcomes.map((item) => item.outcome));
  for (const kind of ["answered", "denied", "silence", "open"]) assert.ok(kinds.has(kind), kind);
  assert.equal(review.openQuestionCount(example.events), example.note.open_questions);

  const segmentIds = new Set(example.note.transcript.map((segment) => segment.id));
  const eventIds = new Set(example.events.map((event) => event.id));
  for (const event of example.events) {
    for (const id of event.segmentIds) assert.ok(segmentIds.has(id), `${event.kind} ${event.id}`);
    if (event.parentEventId != null) assert.ok(eventIds.has(event.parentEventId));
  }
});

test("the example's topics return to the launch date twice and to SSO once, so Auto draws the graph", () => {
  const snapshot = example.note.conversation_topics;
  assert.ok(snapshot.nodes.length >= 6);
  const returns = Object.fromEntries(snapshot.nodes.map((node) => [node.label, node.returns]));
  assert.equal(returns["launch date"], 2);
  assert.equal(returns["sso saml"], 1);
  assert.equal(snapshot.edges.filter((edge) => edge.kind === "return").length, 3);
  assert.equal(flow.suitableView(flow.flowShape(snapshot)).view, "graph");
});

test("the example's marks and loudness read back", () => {
  const marks = moments.parseMoments(example.note.conversation_marks);
  assert.ok(marks.length >= 2 && marks.length <= 3);
  for (const mark of marks) assert.ok(moments.momentSegment(mark, example.note.transcript));
  const levels = loudness.decodeLoudness(JSON.stringify(example.note.conversation_loudness));
  const seconds = (example.meta.endedAt - example.meta.startedAt) / 1000;
  assert.ok(Math.abs(levels.length - seconds) < 3, `${levels.length} levels`);
  assert.ok(levels.every((level) => level.level > 0 && level.level < 1));
});

test("placing moves every time by the same whole seconds, ending well before now", () => {
  const placed = samples.placeSampleConversation(example, { now: NOW });
  const delta = placed.startedAt - example.meta.startedAt;
  assert.equal(placed.startedAt % 1000, 0);
  assert.ok(placed.endedAt <= NOW - samples.SAMPLE_MIN_ENDED_AGO_MS);
  assert.match(placed.note.created_at, /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/);
  assert.equal(
    new Date(`${placed.note.created_at.replace(" ", "T")}Z`).getTime(),
    placed.startedAt
  );

  const transcript = JSON.parse(placed.note.transcript);
  transcript.forEach((segment, index) =>
    assert.equal(segment.timestamp - example.note.transcript[index].timestamp, delta)
  );
  placed.events.forEach((event, index) =>
    assert.equal(event.createdAt - example.events[index].createdAt, delta)
  );
  const marks = JSON.parse(placed.note.conversation_marks);
  marks.forEach((mark, index) => {
    assert.equal(mark.at - example.note.conversation_marks[index].at, delta);
    assert.equal(mark.id, `m-${mark.at}`);
  });
  const runs = JSON.parse(placed.note.conversation_loudness).runs;
  assert.equal(runs[0].at - example.note.conversation_loudness.runs[0].at, delta);
  const nodes = JSON.parse(placed.note.conversation_topics).nodes;
  assert.equal(nodes[0].firstAt - example.note.conversation_topics.nodes[0].firstAt, delta);

  // The point of the margin: Record must not continue the example.
  const asStored = { transcript: placed.note.transcript, created_at: placed.note.created_at };
  assert.equal(resume.findResumableConversation([asStored], { now: NOW }), null);
});

test("a days-ago placement lands on that day at that local time, on a weekday", () => {
  const checkin = demoFixtures.find((fixture) => fixture.meta.id === "sso-fix-checkin");
  // A Tuesday: the day before is a Monday.
  const tuesday = new Date(2027, 5, 15, 19, 0, 0).getTime();
  const monday = new Date(samples.placeSampleConversation(checkin, { now: tuesday }).startedAt);
  assert.equal(monday.getDate(), 14);
  assert.equal(monday.getHours(), 17);
  assert.equal(monday.getMinutes(), 30);
  // A Sunday: the day before is a Saturday, so it moves to Friday.
  const sunday = new Date(2027, 5, 20, 19, 0, 0).getTime();
  const friday = new Date(samples.placeSampleConversation(checkin, { now: sunday }).startedAt);
  assert.equal(friday.getDay(), 5);
  assert.equal(friday.getDate(), 18);
});

test("the demo conversations are samples too, and the map links each to the example", () => {
  assert.ok(demoFixtures.length >= 5);
  const all = [example, ...demoFixtures];
  const conversations = all.map((fixture, index) => {
    const placed = samples.placeSampleConversation(fixture, { now: NOW });
    return {
      id: index + 1,
      title: placed.note.title,
      createdAt: placed.startedAt,
      snapshot: JSON.parse(placed.note.conversation_topics),
    };
  });
  const { edges } = lifetime.buildLifetimeGraph(conversations);
  for (let id = 2; id <= all.length; id += 1) {
    assert.ok(
      edges.some(
        (edge) => (edge.from === 1 && edge.to === id) || (edge.from === id && edge.to === 1)
      ),
      `${all[id - 1].meta.id} is not linked to the example`
    );
  }
});

test("anything that is not a sample fixture is refused", () => {
  assert.throws(() => samples.assertSampleFixture(null));
  assert.throws(() => samples.assertSampleFixture({ kind: "something-else" }));
  assert.throws(() => samples.assertSampleFixture({ ...example, version: 99 }));
  assert.throws(() =>
    samples.placeSampleConversation({ ...example, note: { ...example.note, transcript: [] } })
  );
});
